-- =====================================================================
-- Denim Wholesale WhatsApp AI Agent — Supabase setup
-- Run once in Supabase → SQL Editor → New query → paste → Run
-- Creates the products table (120 demo products), locks it down with RLS,
-- and grants access only to the service_role key used by n8n.
-- =====================================================================

create table if not exists public.products (
  product_id       text primary key,                -- e.g. PD011 (printed on every image)
  product_name     text not null,
  category         text not null check (category in ('Adult Male','Adult Female','Kids Boy','Kids Girl')),
  asking_price     integer not null,                -- TK per piece
  max_discount     integer not null default 20,     -- TK per piece, bargaining limit
  bundle_size      integer not null,                -- pcs per bundle
  moq_bundles      integer not null default 1,
  fit              text,
  color            text,
  fabric           text,
  key_features     text,
  sizes            text,
  size_assortment  text,
  stock_bundles    integer not null default 0,
  stock_status     text check (stock_status in ('In Stock','Low Stock','Made to Order')),
  dispatch_time    text,
  full_details     text,
  search_keywords  text,
  catalog_batch    integer,                         -- 1-6, 20 images per WhatsApp batch
  image_file       text,
  image_url        text,                            -- Cloudinary public URL
  is_active        boolean not null default true,
  updated_at       timestamptz not null default now(),
  -- calculated automatically: change asking_price / max_discount / bundle_size only
  lowest_price     integer generated always as (asking_price - max_discount) stored,  -- bargaining floor
  bundle_price     integer generated always as (asking_price * bundle_size) stored
);

create index if not exists products_category_idx on public.products (category);
create index if not exists products_batch_idx    on public.products (catalog_batch);

-- Security: RLS on, no public (anon/authenticated) access. n8n uses the service_role key.
alter table public.products enable row level security;
revoke all on public.products from anon, authenticated;
grant select, insert, update, delete on public.products to service_role;

-- Keep updated_at fresh on every edit
create or replace function public.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end; $$;
drop trigger if exists products_set_updated_at on public.products;
create trigger products_set_updated_at before update on public.products
for each row execute function public.set_updated_at();

-- Demo data (120 products)
on conflict (product_id) do update set
  product_name = excluded.product_name,
  category = excluded.category,
  asking_price = excluded.asking_price,
  max_discount = excluded.max_discount,
  bundle_size = excluded.bundle_size,
  moq_bundles = excluded.moq_bundles,
  fit = excluded.fit,
  color = excluded.color,
  fabric = excluded.fabric,
  key_features = excluded.key_features,
  sizes = excluded.sizes,
  size_assortment = excluded.size_assortment,
  stock_bundles = excluded.stock_bundles,
  stock_status = excluded.stock_status,
  dispatch_time = excluded.dispatch_time,
  full_details = excluded.full_details,
  search_keywords = excluded.search_keywords,
  catalog_batch = excluded.catalog_batch,
  image_file = excluded.image_file,
  image_url = excluded.image_url,
  is_active = excluded.is_active,
  updated_at = now();

-- Quick check: should return 4 rows totalling 120
select category, count(*) as products, min(asking_price) as min_price, max(asking_price) as max_price
from public.products group by category order by category;
